package com.ai.seller.external.naver

import com.ai.seller.domain.Order
import java.time.Instant

data class NaverOrder(
    val order: OrderInfo,
    val productOrder: ProductOrder,
    val beforeClaim: BeforeClaim?,
    val currentClaim: CurrentClaim?,
    val completedClaims: List<CompletedClaim>?,
    val delivery: Delivery?,
) {
    fun toOrder(imageUrls: List<String>): Order = Order(
        market = Order.Market.NAVER,
        orderId = order.orderId,
        orderedAt = order.orderDate ?: Instant.now(),
        buyer = Order.Buyer(
            name = order.ordererName,
            phone = order.ordererTel,
            address = productOrder.shippingAddress?.let {
                Order.Address(
                    receiverName = it.name,
                    receiverPhone = it.tel1,
                    zipCode = it.zipCode,
                    baseAddress = it.baseAddress,
                    detailAddress = it.detailedAddress,
                )
            },
        ),
        product = Order.Product(
            id = productOrder.productId,
            name = productOrder.productName,
            option = productOrder.productOption,
            quantity = productOrder.quantity ?: 0,
            unitPrice = productOrder.unitPrice ?: 0,
            imageUrls = imageUrls,
        ),
        payment = Order.Payment(
            totalAmount = productOrder.totalPaymentAmount ?: 0,
            productAmount = productOrder.totalProductAmount ?: 0,
            deliveryFee = productOrder.deliveryFeeAmount ?: 0,
            discountAmount = productOrder.productDiscountAmount ?: 0,
        ),
    )

